list_payment_gateways.code:
import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.paymentGateways().listPaymentGateways(
        Map.of("limit", 20, "offset", 0, "promotional", "false"));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("payment_gateways")) {
    Map<?, ?> gateway = (Map<?, ?>) row;
    System.out.println(gateway.get("id") + " " + gateway.get("code") + " " + gateway.get("name") + " "
            + gateway.get("enabled") + " " + gateway.get("default"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("has_next"));

